from z3 import *

n = 12
X = [[Int(f"x_{i}_{j}") for j in range(n)] for i in range(n)]

s = Solver()

# Domain
for i in range(n):
    for j in range(n):
        s.add(X[i][j] >= 0, X[i][j] < n)

# Latin square
for i in range(n):
    s.add(Distinct(X[i]))
for j in range(n):
    s.add(Distinct([X[i][j] for i in range(n)]))

# Idempotent
for i in range(n):
    s.add(X[i][i] == i)

# QG3: x[ x[i][j] ][ x[j][i] ] = i
# We can encode this using uninterpreted functions or just boolean variables,
# but Z3 can handle array/function or just nested indexing if we use a function.
# Let's use a Function.
f = Function('f', IntSort(), IntSort(), IntSort())

for i in range(n):
    for j in range(n):
        s.add(f(i, j) == X[i][j])

for i in range(n):
    for j in range(n):
        s.add(f(f(i, j), f(j, i)) == i)

# Symmetry breaking?
# QG3 implies x[x[i][j]][x[j][i]] = i.
# If we swap i and j, x[x[j][i]][x[i][j]] = j.
# So if x[i][j] = u and x[j][i] = v, then x[u][v] = i and x[v][u] = j.

s.set("timeout", 50000)
if s.check() == sat:
    m = s.model()
    res = []
    for i in range(n):
        for j in range(n):
            res.append(m.evaluate(X[i][j]).as_long())
    print("SAT")
    print(res)
else:
    print("UNSAT or TIMEOUT")

import time
from pysat.solvers import Cadical153

n = 12
# Variables: v(i, j, k) = i * n^2 + j * n + k + 1
def v(i, j, k):
    return i * n * n + j * n + k + 1

solver = Cadical153()

# Exactly one k for each i, j
for i in range(n):
    for j in range(n):
        solver.add_clause([v(i, j, k) for k in range(n)])
        for k1 in range(n):
            for k2 in range(k1 + 1, n):
                solver.add_clause([-v(i, j, k1), -v(i, j, k2)])

# Exactly one j for each i, k
for i in range(n):
    for k in range(n):
        solver.add_clause([v(i, j, k) for j in range(n)])
        for j1 in range(n):
            for j2 in range(j1 + 1, n):
                solver.add_clause([-v(i, j1, k), -v(i, j2, k)])

# Exactly one i for each j, k
for j in range(n):
    for k in range(n):
        solver.add_clause([v(i, j, k) for i in range(n)])
        for i1 in range(n):
            for i2 in range(i1 + 1, n):
                solver.add_clause([-v(i1, j, k), -v(i2, j, k)])

# Idempotent
for i in range(n):
    solver.add_clause([v(i, i, i)])

# QG3: x[i][j] = u and x[j][i] = v => x[u][v] = i
# -v(i, j, u) or -v(j, i, v) or v(u, v, i)
for i in range(n):
    for j in range(n):
        if i == j: continue
        for u in range(n):
            for v_val in range(n):
                solver.add_clause([-v(i, j, u), -v(j, i, v_val), v(u, v_val, i)])

print("Solving...")
start = time.time()
res = solver.solve()
print("Time:", time.time() - start)
if res:
    print("SAT")
    model = solver.get_model()
    grid = []
    for i in range(n):
        for j in range(n):
            for k in range(n):
                if model[v(i, j, k) - 1] > 0:
                    grid.append(k)
    print(grid)
else:
    print("UNSAT")

