n = 12
def v(i, j, k):
    return i * n * n + j * n + k + 1

def solve():
    solver = Solver(name='m22') # MapleCM

    # Exactly one k for each i, j
    for i in range(n):
        for j in range(n):
            solver.add_clause([v(i, j, k) for k in range(n)])
            for k1 in range(n):
                for k2 in range(k1 + 1, n):
                    solver.add_clause([-v(i, j, k1), -v(i, j, k2)])

    # Exactly one j for each i, k
    for i in range(n):
        for k in range(n):
            solver.add_clause([v(i, j, k) for j in range(n)])
            for j1 in range(n):
                for j2 in range(j1 + 1, n):
                    solver.add_clause([-v(i, j1, k), -v(i, j2, k)])

    # Exactly one i for each j, k
    for j in range(n):
        for k in range(n):
            solver.add_clause([v(i, j, k) for i in range(n)])
            for i1 in range(n):
                for i2 in range(i1 + 1, n):
                    solver.add_clause([-v(i1, j, k), -v(i2, j, k)])

    # Idempotent
    for i in range(n):
        solver.add_clause([v(i, i, i)])

    # QG3
    for i in range(n):
        for j in range(n):
            if i == j: continue
            for u in range(n):
                for v_val in range(n):
                    solver.add_clause([-v(i, j, u), -v(j, i, v_val), v(u, v_val, i)])

    # Symmetry breaking
    # We can fix the first row to some extent? No, it's a quasigroup, not a loop.
    # But we can rename elements.
    # Since it's idempotent, 0*0=0, 1*1=1, etc.
    # We can fix 0*1 = 2, 1*0 = 3.
    solver.add_clause([v(0, 1, 2)])
    solver.add_clause([v(1, 0, 3)])

    print("Solving...")
    start = time.time()
    res = solver.solve()
    print("Time:", time.time() - start)
    if res:
        print("SAT")
        model = solver.get_model()
        grid = []
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    if model[v(i, j, k) - 1] > 0:
                        grid.append(k)
        print(grid)
    else:
        print("UNSAT")

